/** ALRINT-REC (copy CITIDIRECT/S151/FORMATO/ARCHIVO/ALR): un renglón de la interfase ALR de CitiDirect. */
public record AlrRecord(
        String recordType,          // X(03)  "ALR"
        // ALRINT-KEY-GRP X(83) redefinido
        int    branchNbr,           // 9(03)  siempre 485 (p151.citi.branch)
        long   custNbr,             // 9(12)
        int    ccyNbr,              // 9(03)  000 MXN, 126 USD
        String acctNbr1,            // 9(12)  String: conserva ceros a la izquierda
        String acctNbr2,            // 9(23)
        LocalDate valDate,          // 9(06)  ver FechaCiti.aammdd()
        String ctrctRefNbr,         // X(16)
        int    currentNo,           // 9(08)
        String prodType, String subsystemCode, char ctrctStatInd,
        int    txnCode,             // 9(04)
        char   drCrInd,             // 'D' | 'C'
        long   compnRefNbr, long dispAcctNbr,
        LocalDate txnDate,          // 9(06)
        BigDecimal txnAmt,          // 9(15)V9(02) -> escala 2
        char   txnAmtSign,          // '+' | '-'
        int    ctrctHistSeqNbr, String theirRefNbr, int dispInd,
        String swiftCcyCode,        // X(04)  "MXN " | "USD "
        char   revrsInd,            // ' '
        int    textLineCount,       // 9(01)  siempre 5
        List<String> textLines,     // X(175) = 5 x X(35), ALRINT-TEXT-LINES-R
        String origFile) {          // X(02)  "LQ"

    public AlrRecord {
        if (textLines.size() != 5) throw new IllegalArgumentException("ALR exige 5 líneas de texto");
        textLines = textLines.stream().map(t -> Fixed.padRight(t, 35)).toList();
    }

    /** Serializa exactamente al layout de 384 posiciones que lee CitiDirect (REGISTRO-ALR X(384)). */
    public String toFixed() { return AlrLayout.write(this); }
}

