@Component
@RequiredArgsConstructor
public class TransferenciaCitiTasklet implements Tasklet {

    private final CitiDirectGateway citi;      // Spring Integration SFTP hacia /CO/ de CitiDirect
    private final P151Properties props;

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        var p = ctx.getStepContext().getJobParameters();
        // WKS-TIT-WFL: START <prog> ("S" sistema archivo "C", fecha, csi)
        String archivo = "S%03d%sC".formatted((Long) p.get("sistema"), "ALR");
        ResultadoEnvio r = citi.enviar(archivo, (String) p.get("fechaProceso"), props.numCsi());
        if (!r.exitoso()) {
            // CALL SYSTEM WFL no espera ni revisa el resultado de P940; aquí sí se falla el step.
            throw new TransferenciaCitiException(archivo, r.detalle());
        }
        return RepeatStatus.FINISHED;
    }
}

@Service
@RequiredArgsConstructor
public class SaldoInicioDiaService {

    private static final int MAX_INTENTOS = 8;                       // W77-REINTENTO = 8
    private static final Duration ESPERA = Duration.ofSeconds(30);   // WAIT(30)
    private static final Set<Integer> NO_DISPONIBLE = Set.of(5, 17);

    private final SaldosClient s500;            // reemplaza S500L020SDOINIDIA IN S500L020SDOS
    private final SaldoCacheRepository cache;   // ARCH-SAL (VML), JPA
    private final LlamadaSaldoRepository bitacora;  // ARCHIVO-ERROR: el COBOL escribe un renglón por llamada

    /** 35200-CALL-S500. Saldo real = inicio de día del 500 menos inicio de día del 408. */
    @Transactional
    public BigDecimal saldoReal(String contrato, LocalDate fechaProceso) {
        for (int intento = 1; ; intento++) {
            RespuestaSaldo r = s500.saldoInicioDia(contrato, fechaProceso);
            bitacora.save(LlamadaSaldo.de(fechaProceso, contrato, r));   // WRITE REG-ARCH-ERROR, incluso con éxito
            switch (r.resultado()) {
                case 0 -> {
                    BigDecimal saldo = r.saldo500().subtract(r.saldo408());   // COMPUTE, resta exacta
                    cache.save(new SaldoCache(contrato, fechaProceso, r.saldo500(), r.saldo408(), saldo));
                    return saldo;
                }
                case 5, 17 -> {
                    if (intento < MAX_INTENTOS) { pausa(ESPERA); continue; }
                    // COBOL: registra el error, regresa el contador a 0 y el PERFORM UNTIL sigue sin límite.
                    throw new LibreriaSaldosNoDisponibleException(contrato, r.resultado());
                }
                case 12 -> // COBOL: registra el error sin encender W77-BAN-S500 y vuelve a llamar sin espera.
                    throw new LibreriaSaldosException(contrato, r.resultado());
                default -> {
                    log.info("S500L020 devolvió {} para {}: se continúa con saldo 0", r.resultado(), contrato);
                    return BigDecimal.ZERO.setScale(2);                // MOVE ZEROS TO W77-SALDO
                }
            }
        }
    }
}

@Bean
Step generaArchivosCiti(JobRepository repo, PlatformTransactionManager tx,
                        FlatFileItemReader<MovimientoCiti> archCiticTd,      // ARCH-CITICTD
                        MovimientoCitiProcessor processor,
                        ClassifierCompositeItemWriter<RegistroCiti> writer) {   // ALR / AHR / OCM
    return new StepBuilder("40000-GENERA-ARCHIVOS", repo)
            .<MovimientoCiti, List<RegistroCiti>>chunk(100, tx)   // BLOCK CONTAINS 100 RECORDS del ALR
            .reader(archCiticTd)
            .processor(processor)
            .writer(Flatten.of(writer))
            .listener(new ContadoresAlrOcmListener())            // W77-CONTADOR-ALR/OCM en cero por corrida
            .build();
}

@Component
@StepScope
@RequiredArgsConstructor
public class MovimientoCitiProcessor implements ItemProcessor<MovimientoCiti, List<RegistroCiti>> {

    private static final IntRange CLAVES_IMPORTE_EN_TEXTO = IntRange.of(731, 746);  // > 730 AND < 747

    /** 41000-GRABA-ARCHIVOS-CITI. */
    @Override
    public List<RegistroCiti> process(MovimientoCiti m) {
        IndicadorEnvio envio = IndicadorEnvio.de(m.envioCd());        // MOVE RMC-ENVIO-CD TO WKS-IND
        MovimientoCiti mov = m;
        String importeComoTexto = null;
        if (CLAVES_IMPORTE_EN_TEXTO.contains(m.cveTran())) {
            importeComoTexto = Fixed.importeEditado(m.importe());    // WKS-DATO-IMP-EDIT
            mov = m.conImporte(BigDecimal.ZERO.setScale(2));         // MOVE ZEROS TO RMC-IMPORTE
        }
        var salida = new ArrayList<RegistroCiti>(3);
        alr(mov, envio, importeComoTexto).ifPresent(salida::add);
        ahr(mov, envio, importeComoTexto).ifPresent(salida::add);
        ocm(mov, envio).ifPresent(salida::add);
        return salida.isEmpty() ? null : salida;                     // IND-SIS = 0: no va a ningún archivo
    }
}

/** 41210-VALIDA-NATURALEZA-ALR: afectación del catálogo, luego naturaleza contable, luego excepción 731-746. */
static char drCr(int cveTran, CatalogoTransacciones cat) {
    if (cveTran > 730 && cveTran < 747) return 'C';           // se evalúa al final y siempre gana
    return switch (cat.afectacion(cveTran)) {                 // WKS-PT-AFECTACION: 1 cargo, 2 abono
        case 1 -> 'D';
        case 2 -> 'C';
        default -> switch (cat.naturalezaContable(cveTran)) { // WKS-PT-NATCONT
            case 1 -> 'D';
            case 2 -> 'C';
            default -> ' ';    // ninguna rama asigna: el campo conserva lo que traía el buffer
        };
    };
}

/** 41210-VALIDA-MON1-ALR y 41210-VALIDA-MON2-ALR. */
enum Monedas {
    MXN(1, 0, "MXN "), USD(5, 126, "USD ");
    final int moneda, ccyNbr; final String swift;
    Monedas(int m, int c, String s) { moneda = m; ccyNbr = c; swift = s; }

    static int ccyNbr(int moneda)  { return de(moneda).ccyNbr; }
    static String swift(int moneda) { return de(moneda).swift; }
    static Monedas de(int moneda) {
        return Arrays.stream(values()).filter(x -> x.moneda == moneda).findFirst()
                .orElseThrow(() -> new MonedaNoMapeadaException(moneda));   // COBOL deja el valor previo
    }
}

/** 41210-VALIDA-IMPORTE-ALR. RMC-IMPORTE es PIC 9(14)V99 sin signo: en la práctica siempre '+'. */
static char signo(BigDecimal importe) { return importe.signum() < 0 ? '-' : '+'; }

@Bean
ClassifierCompositeItemWriter<RegistroCiti> writerCiti(BneProperties bne, HostInfo host,
        FlatFileItemWriter<RegistroCiti> archAlr, FlatFileItemWriter<RegistroCiti> archAlrBne,
        FlatFileItemWriter<RegistroCiti> archAhr, FlatFileItemWriter<RegistroCiti> archAhrBne,
        FlatFileItemWriter<RegistroCiti> archOcm, FlatFileItemWriter<RegistroCiti> archOcmBne) {

    boolean hostBne = bne.habilitado(host.nombre());              // W88-HOSTNAME
    var writer = new ClassifierCompositeItemWriter<RegistroCiti>();
    writer.setClassifier(reg -> {
        // 41300-ARCHIVO-ALR/AHR/OCM: un mismo registro puede ir a los dos destinos.
        List<ItemWriter<? super RegistroCiti>> destinos = new ArrayList<>(2);
        if (hostBne && reg.envio().vaABne())      destinos.add(bneDe(reg, archAlrBne, archAhrBne, archOcmBne));
        if (reg.envio().vaACitiDirect())          destinos.add(cdDe(reg, archAlr, archAhr, archOcm));
        return destinos.isEmpty() ? items -> { } : new CompositeItemWriter<>(destinos);
        // CompositeItemWriter también escribe el renglón del listado CTD (300-100-DETALLE-ALR).
    });
    return writer;
}
